<?php
namespace App\Filament\Admin\Resources\Policies\Pages;use App\Filament\Admin\Concerns\ServiceValidation;use App\Filament\Admin\Resources\Policies\PolicyResource;use App\Models\{CertificateTemplate,StickerStock};use Filament\Actions\Action;use Filament\Forms\Components\{DateTimePicker,KeyValue,Select,TextInput,Textarea};use Filament\Resources\Pages\ViewRecord;final class ViewPolicy extends ViewRecord{protected static string $resource=PolicyResource::class;protected function getHeaderActions():array{return[Action::make('service')->label('Policy service')->icon('heroicon-o-arrows-right-left')->visible(fn()=>in_array($this->record->status,['ACTIVE','SUSPENDED','EXPIRED'],true))->schema([Select::make('type')->options(['ENDORSEMENT'=>'Endorsement','CANCELLATION'=>'Cancellation','REINSTATEMENT'=>'Reinstatement'])->required()->native(false),DateTimePicker::make('effective_at')->required(),KeyValue::make('requested_changes'),TextInput::make('premium_delta_minor')->numeric()->required()->default(0),TextInput::make('reason_code')->required()->maxLength(64),Textarea::make('notes')->maxLength(2000)])->action(function(array$d){if(ServiceValidation::run(fn()=>app(\App\Application\Policies\PolicyServicingService::class)->request($this->record,$d,auth()->user()))===null)return;}),Action::make('issueCertificate')->label('Issue certificate')->icon('heroicon-o-qr-code')->visible(fn()=>$this->record->status==='ACTIVE')->schema([Select::make('certificate_template_id')->options(fn()=>CertificateTemplate::where('status','ACTIVE')->pluck('code','id'))->required()->searchable(),TextInput::make('serial_number')->required()->maxLength(100),TextInput::make('document_hash')->required()->length(64),Select::make('sticker_serial_number')->options(fn()=>StickerStock::where(['carrier_id'=>$this->record->carrier_id,'custodian_tenant_id'=>$this->record->tenant_id,'status'=>'IN_STOCK'])->pluck('serial_number','serial_number'))->searchable()])->action(function(array$d){if(ServiceValidation::run(fn()=>app(\App\Application\Certificates\CertificateService::class)->issue($this->record,CertificateTemplate::findOrFail($d['certificate_template_id']),$d,auth()->user()))===null)return;})];}}
